INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5566, 'Martin H. Greenberg', '1941-03-01', '2011-06-25', 'United States', 'Martin Harry Greenberg (March 1, 1941 – June 25, 2011) was an American academic and anthologist in many genres, including mysteries and horror, but especially in speculative fiction. In all, he compiled 1,298 anthologies and commissioned over 8,200 original short stories. He founded Tekno Books, a packager of more than 2000 published books. He was also a co-founder of the Sci-Fi Channel. Greenberg was also an expert in terrorism and the Middle East. He was a longtime friend, colleague and business partner of Isaac Asimov.');
INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5567, 'Claude Guillon', '1952-09-17', '2023-01-19', 'France', NULL);
INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5568, 'Katherine V. Forrest', '1939-04-20', NULL, 'Canada', 'Katherine V. Forrest is a Canadian-born American writer, known for her novels about lesbian police detective Kate Delafield.');
INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5569, 'Tomas Tranströmer', '2015-03-26', NULL, 'Sweden', 'Swedish writer, poet and translator, whose poetry has been translated into over 60 languages. He was awarded the 2011 Nobel Prize in Literature.');
INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5570, 'Wassily Kandinsky', NULL, NULL, NULL, '**Wassily Wassilyevich Kandinsky** was a Russian painter and art theorist active in Germany during the late [Belle Époque](https://en.wikipedia.org/wiki/Belle_%C3%89poque "Belle Époque") and [Interwar eras](https://en.wikipedia.org/wiki/Interwar_era "Interwar era"). Kandinsky is generally credited as one of the pioneers of [abstraction](https://en.wikipedia.org/wiki/Abstract_art "Abstract art") in [Western art](https://en.wikipedia.org/wiki/Western_art "Western art"). Born in Moscow, he began painting studies (life-drawing, sketching and anatomy) at the age of 30.');
INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5571, 'Stendhal', '1783-01-23', '1842-03-23', 'France', 'Stendhal était le pseudonyme de l''écrivain français du XIXe siècle Marie-Henri Beyle. Reconnu pour son analyse fine de la psychologie de ses personnages, il est considéré comme l''un des premiers et des plus importants représentants du réalisme dans ses deux romans, *Le Rouge et le Noir* (1830) et *La Chartreuse de Parme* (1839). ---------- Stendhal was the pseudonym of the 19th-century French writer Marie-Henri Beyle. Known for his acute analysis of his characters'' psychology, he is considered one of the earliest and foremost practitioners of realism in his two novels *Le Rouge et le Noir* (The Red and the Black, 1830) and *La Chartreuse de Parme* (The Charterhouse of Parma, 1839).');
