INSERT INTO public.author (id, full_name, birth_date, death_date, nationality, biography) VALUES (5575, 'His Holiness Tenzin Gyatso the XIV Dalai Lama', '1935-07-06', NULL, NULL, 'His Holiness the 14th Dalai Lama, Tenzin Gyatso, a Buddhist monk, is the most influential figure in the Gelugpa sect of Tibetan Buddhism and the spiritual leader of the Tibetan people.');
