INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (7938, '0505522845', 'Jaguar eyes', NULL, 'Nobleman by birth, naturalist by training, and adventurer at heart, Daniel Heywood ventured into the wilds of the Amazon, determined to leave his mark on science. Wounded by Indians shortly into his journey, he was rescued by a beautiful woman with the longest legs he''d ever seen. As she nursed him back to health, Daniel realized he had stumbled upon an undiscovered civilization, a people that would prove his friend Darwin''s theory correct. But science could not explain the way his heart skipped a beat when he looked into the captivating beauty''s gold-green eyes. Vanessa had never seen a naked man before, but one look at the wounded Englishman''s muscular form told her he was something special. Defying the ways of her people, she returned with him to England. But she soon wondered if she was really the object of his affections—or a subject in his experiment. The answer would lie in Daniel''s willingness to do as she had done, to leave con', 1998, 'EN', 362, 'Dorchester Pub. Co.', '/covers/catalogue/ol-cover-317517.jpg', 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
