INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8103, '9782843374920', 'Traité à l''usage de mes potes de droite qui ont du mal à kiffer la France de Diam''s', NULL, 'Au cŒur de cette réflexion se trouve la question de la représentation du vivant : aujourd''hui, vivre ce n''est plus seulement résister à la mort, selon le mot de Bichat, ou sélectionner c''est-à-dire conserver des variations "utiles" dans un contexte donné, selon la théorie darwinienne de l''évolution, mais aussi être capable de faire usage de la mort, de négocier en permanence avec elle en ne cessant à la fois de l''initier et de la suspendre.', 2008, 'FR', 142, 'Carrière', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
