INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8112, '1844300269', 'Sahara', 'the Atlantic to the Nile', 'One of the greatest artistic photography collections of the Sahara, showing its people, the tribes, costumes, landscape and the fantastic light of the immense expanse straddling the Tropic of Cancer and running from the Atlantic Sea to the Nile Valley. Teaches about the culture from Layan to Morocco, via the Aswan in Egypt and crossing Tunisia, Algeria, and the lands of Libya.', 2001, 'EN', 191, 'Hachette Illustrated', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
