INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8156, '0312271859', 'Red, white, and blue murder', NULL, 'It hasn''t rained in two months, and the sweltering heat has everything and everyone primed to erupt. First, Sheriff Rhodes must keep his cool when a local reporter accuses him and other elected officials of corruption. Next, a hunting shack mysteriously burns to the ground with a good ''ole boy county commissioner inside. Someone wanted him dead - but who?', 2003, 'EN', 215, 'Thomas Dunne Books', '/covers/catalogue/ol-cover-177775.jpg', 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
