INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8159, '031220907X', 'A romantic way to die', 'a Sheriff Dan Rhodes mystery', '"Dan Rhodes, the sheriff of Blacklin County, Texas, has seen more than his share of strange events during his time in office, most recently he exorcised a ghost from the county jail, but nothing could have prepared him for the group of writers that has descended upon blacklin County."--Jacket.', 2001, 'EN', 231, 'Thomas Dunne Books', '/covers/catalogue/ol-cover-175892.jpg', 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8160, '9072828070', 'Henry Moore', 'sculpturen, tekeningen = sculptures, drawings : 23-5-1999/15-8-1999, Openluchtmuseum voor Beeldhouwkunst Middelheim, Museum van Hedendaagse Kunst Antwerpen', 'This seventh and final volume in the complete catalogue of Henry Moore''s drawings provides a key to the material contained in the other six volumes. It gives a consolidated version of all the reference apparatus contained in each of the other volumes (index, concordance and list of exhibitions), enabling the user to track down any particular drawing from any period or volume by means of its title, HMF or AG number. In addition, this volume includes a list of addenda and corrigenda relating to information that has come to light since this series was launched in 1994. Some 150 items are included in this section. The opportunity has also been seized to catalogue about 600 previously unpublished drawings produced by Moore in the last two years of his life (1984-86) and held in the archives of the Henry Moore Foundation. About 50 of these are illustrated and give a flavour of the fine quality of the artist''s output even as he approached the end of his life.', 1999, 'NL', 138, 'Stad Antwerpen', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8161, NULL, 'Christina Kubisch, Fabrizio Plessi', 'Konzerte, video performances, Installationen : [Ausstellung], Neue Galerie Sammlung Ludwig, Aachen, Internationaal Cultureel Centrum, Antwerpen', NULL, 1979, 'NL', 49, 'Neue Galerie', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8162, '9789057791192', 'James Ensor', 'the complete prints', '"Belgian painter James Ensor (1860-1949) created a body of work that is comical, ironic and profound, which can be interpreted in many ways.'' To a large degree his work is self-referential, both foreshadowing and reflecting back upon itself and containing many simultaneous strands of development and parallel phenomena." "Ensor''s unusual motifs, which became distinctive symbols for the absurdity of life, have fascinated and influenced other artists from all other periods since then in view of new tendencies in contemporary art such as the manifestation of the grotesque and comic, Ensor''s work is yet again current. Featuring almost 80 masterpieces on canvas and over no works on paper-both drawings and prints - this monograph presents key works from all periods of his career. Special focus is given to the artist''s later works, which have long been neglected by art historians."--BOOK JACKET', 2010, 'NL', 303, 'Frank Deceuninck, Defiac nv', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
