INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8190, '9780739459881', 'This Rake of Mine (The Bachelor Chronicles)', NULL, NULL, 2005, 'EN', NULL, 'Avon Books', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8191, '9780743475051', 'We''ll Always Have Murder', 'A Humphrey Bogart Mystery', 'Humphrey Bogart and down-and-out Hollywood private-eye Terry Scott team up to thwart a scheme to blackmail Bogie for murder and find themselves tangling with gangsters and trying not to trip over corpses. Their investigation takes them to glamorous restaurants like The Brown Derby, where the stars go to be seen, and to other, darker, more dangerous places where names are changed and faces are hidden from public view.As Bogie and Terry dig deeper, they uncover too many secrets that someone doesn''t want known, and they find themselves the targets of a killer. Getting through alive will take all the smarts, toughness and grit of a character in a Humphrey Bogart movie!', 2003, 'EN', 240, 'I Books', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
