INSERT INTO public.title (id, isbn, title, subtitle, summary, publication_year, language, page_count, publisher, cover_image_url, title_status, created_at, updated_at) VALUES (8197, '9783446182998', 'Omeros.', NULL, 'A poem in five books, of circular narrative design, titled with the Greek name for Homer, which simultaneously charts two currents of history: the visible history charted in events -- the tribal losses of the American Indian, the tragedy of African enslavement -- and the interior, unwritten epic fashioned from the suffering of the individual in exile.', 1995, 'DE', 343, 'Carl Hanser', NULL, 'ACTIVE', '2026-09-04 11:19:06.861493+02', '2026-09-04 11:19:06.861493+02');
